"""Optional bounded XY refinement of an already constructed flat separator.

This does not choose topology, alter a boundary or relax a publication guard.
The caller still validates the complete separator and its weld to pavement.
Only quad meshes carrying the existing _separator_key and st_cn_height
contracts are inputs. A zero display exaggeration does not make a graded
physical surface eligible for planar redistribution.
"""
import bpy

from . import boundary_quad_bridge_nodes as bridge
from .path_surface_nodes import _Nodes

NAME='Prochitecture Streets / Pinned separator XY quality v1'
STEPS=64
START_RATIO=6.
FULL_RATIO=12.


def metrics(g,geometry):
    """Longest/shortest XY edge ratio and corner bounds on complete quads."""
    corner=g.node('GeometryNodeInputIndex','Separator quad corner').outputs[0]
    pos=g.node('GeometryNodeInputPosition','Current separator coordinates').outputs[0]
    points=[]
    for offset in range(4):
        at=g.node('GeometryNodeOffsetCornerInFace','Local quad corner '+str(offset))
        g.set(corner,at.inputs['Corner Index']);at.inputs['Offset'].default_value=offset
        vertex=g.node('GeometryNodeVertexOfCorner','Vertex at quad corner '+str(offset))
        g.set(at.outputs['Corner Index'],vertex.inputs['Corner Index'])
        point=g.sample(geometry,pos,vertex.outputs['Vertex Index'],'FLOAT_VECTOR')
        points.append(g.xyz(g.component(point,'X'),g.component(point,'Y')))
    edges=[g.vector('SUBTRACT',points[(i+1)%4],points[i]) for i in range(4)]
    lengths=[g.vector('LENGTH',edge) for edge in edges]
    low=high=lengths[0]
    for length in lengths[1:]:
        low=g.math('MINIMUM',low,length);high=g.math('MAXIMUM',high,length)
    ratio=g.math('DIVIDE',high,g.math('MAXIMUM',low,1e-15))
    cross=g.component(g.vector('CROSS_PRODUCT',edges[0],edges[1]),'Z')
    scaled=g.math('DIVIDE',cross,g.math('MAXIMUM',g.math('MULTIPLY',lengths[0],lengths[1]),1e-30))
    return (g.stat(geometry,ratio,domain='CORNER',output='Max'),
            g.stat(geometry,scaled,domain='CORNER'),
            g.stat(geometry,cross,domain='CORNER'))


def build(*, steps=STEPS):
    if type(steps) is not int or not 1 <= steps <= 512:
        raise ValueError('XY refinement requires a bounded integer iteration count')
    name=NAME if steps==STEPS else NAME+' / '+str(steps)+' iterations'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    tree=bpy.data.node_groups.new(name,'GeometryNodeTree');g=_Nodes(tree)
    tree.interface.new_socket(name='Geometry',in_out='INPUT',socket_type='NodeSocketGeometry')
    for key,kind in (('Geometry','NodeSocketGeometry'),('Applied','NodeSocketBool'),
                     ('Blend','NodeSocketFloat'),('Before Ratio','NodeSocketFloat'),
                     ('After Ratio','NodeSocketFloat')):
        tree.interface.new_socket(name=key,in_out='OUTPUT',socket_type=kind)
    inp=g.node('NodeGroupInput','An already constructed flat separator')
    out=g.node('NodeGroupOutput','Checked improvement or unchanged original')
    geometry=inp.outputs['Geometry']
    pos=g.node('GeometryNodeInputPosition','Keep original height').outputs[0]
    index=g.node('GeometryNodeInputIndex','Same vertex and topology throughout').outputs[0]
    key=g.node('GeometryNodeInputNamedAttribute','Existing exact boundary identity')
    key.data_type='FLOAT_VECTOR';key.inputs['Name'].default_value='_separator_key'
    height=g.node('GeometryNodeInputNamedAttribute','Original physical separator height')
    height.data_type='FLOAT';height.inputs['Name'].default_value='st_cn_height'
    pinned=g.compare(g.component(key.outputs['Attribute'],'X'),0.)
    before,old_angle,old_cross=metrics(g,geometry)
    z=g.component(pos,'Z')
    flat=g.compare(g.math('SUBTRACT',g.stat(geometry,z,output='Max'),g.stat(geometry,z)),0.,'LESS_EQUAL')
    physical_flat=g.compare(g.math('SUBTRACT',g.stat(geometry,height.outputs['Attribute'],output='Max'),
        g.stat(geometry,height.outputs['Attribute'])),0.,'LESS_EQUAL')
    eligible=g.all(g.stat(geometry,key.outputs['Exists']),g.stat(geometry,height.outputs['Exists']),flat,physical_flat,
        g.compare(old_cross,1e-10,'GREATER_THAN'),g.compare(before,START_RATIO,'GREATER_THAN'))
    t=g.math('MINIMUM',1.,g.math('MAXIMUM',0.,g.math('DIVIDE',
        g.math('SUBTRACT',before,START_RATIO),FULL_RATIO-START_RATIO)))
    strength=g.math('MULTIPLY',g.math('MULTIPLY',t,t),g.math('SUBTRACT',3.,g.math('MULTIPLY',2.,t)))
    origin=g.sample(geometry,pos,0,'FLOAT_VECTOR')
    local=bridge._position(g,geometry,g.vector('SUBTRACT',pos,origin))
    begin=g.node('GeometryNodeRepeatInput','Fixed boundary and fixed heights')
    end=g.node('GeometryNodeRepeatOutput','At most sixty-four local averages' if steps==STEPS else 'At most '+str(steps)+' local averages')
    end.repeat_items.clear();end.repeat_items.new('GEOMETRY','Geometry')
    begin.pair_with_output(end);begin.inputs['Iterations'].default_value=steps
    g.set(local,begin.inputs['Geometry'])
    blur=g.node('GeometryNodeBlurAttribute','One local neighbor average')
    blur.data_type='FLOAT_VECTOR';blur.inputs['Iterations'].default_value=1
    g.set(pos,blur.inputs['Value'])
    next_position=g.xyz(g.component(blur.outputs['Value'],'X'),g.component(blur.outputs['Value'],'Y'),z)
    moved=bridge._position(g,begin.outputs['Geometry'],g.switch(pinned,next_position,pos,'VECTOR'))
    g.set(moved,end.inputs['Geometry'])
    original=g.sample(geometry,pos,index,'FLOAT_VECTOR')
    restored=g.vector('ADD',pos,origin)
    blended=g.vector('ADD',original,g.vector('SCALE',g.vector('SUBTRACT',restored,original),strength))
    blended=g.xyz(g.component(blended,'X'),g.component(blended,'Y'),g.component(original,'Z'))
    refined=bridge._position(g,end.outputs['Geometry'],g.switch(pinned,blended,original,'VECTOR'))
    # An ineligible input never needs the averaging branch. No helper
    # attributes are added to the surface or to its surrounding pavement.
    candidate=g.switch(eligible,geometry,refined,'GEOMETRY')
    after,new_angle,new_cross=metrics(g,candidate)
    accepted=g.all(eligible,g.compare(new_cross,1e-10,'GREATER_THAN'),
        g.compare(new_angle,old_angle,'GREATER_EQUAL'),g.compare(after,before,'LESS_THAN'))
    g.set(g.switch(accepted,geometry,candidate,'GEOMETRY'),out.inputs['Geometry'])
    g.set(accepted,out.inputs['Applied']);g.set(g.switch(accepted,0.,strength),out.inputs['Blend'])
    g.set(before,out.inputs['Before Ratio']);g.set(g.switch(accepted,before,after),out.inputs['After Ratio'])
    tree['st_quality_steps']=steps
    tree['st_quality_start_ratio']=START_RATIO;tree['st_quality_full_ratio']=FULL_RATIO
    return tree
